// Whose face the page shows, and the stamp that says so. Browser-safe: the page, the server and
// the static demo all read it. The canvas placeholder (FAKE) is an illustration, so it says it is
// not a person and not YouCam. A replayed face generated by the YouCam AI Image Generator is a
// photo-real image of no one, so it says that; it is never called synthetic, which would read as
// the placeholder. A replay without a generated persona, and live mode, carry no stamp.

export const GENERATED_PERSONA_SOURCE = "youcam-ai-image-generator";

export const FACE_STAMP = Object.freeze({
  synthetic: "SYNTHETIC · not a person · not YouCam",
  generated: "AI-generated · not a real person",
});

// recording.json's persona block, kept to its three fields; anything else is dropped.
export function personaOf(recording) {
  const p = recording?.persona;
  if (!p || typeof p !== "object") return null;
  return { source: String(p.source ?? ""), model: String(p.model ?? ""), promptSha256: String(p.promptSha256 ?? "") };
}

export function faceStampFor(modeId, persona = null) {
  if (modeId === "fake") return FACE_STAMP.synthetic;
  if (modeId === "replay" && persona?.source === GENERATED_PERSONA_SOURCE) return FACE_STAMP.generated;
  return null;
}
